function DentrixConfig({close,refresh}){
 const[url,setUrl]=useState(''),[token,setToken]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState(''),[saved,setSaved]=useState(false),[test,setTest]=useState(null),[testing,setTesting]=useState(false)
 const save=async()=>{if(!url.trim()||!token.trim()){setError('Bridge URL and token are both required.');return}setBusy(true);setError('');try{const t=await idToken();const r=await fetch('/api/secrets',{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${t}`},body:JSON.stringify({dentrixBridgeUrl:url.trim(),dentrixBridgeToken:token.trim()})});const d=await r.json();if(!r.ok)throw new Error(d.error||'Save failed.');setSaved(true);await refresh()}catch(e){setError(e.message)}finally{setBusy(false)}}
 const runTest=async()=>{setTesting(true);setTest(null);try{const t=await idToken();const r=await fetch('/api/dentrix',{headers:{Authorization:`Bearer ${t}`},cache:'no-store'});const d=await r.json();setTest(d.ok&&d.reachable?(d.db&&d.db.connected?{ok:true,msg:'Bridge reachable · database connected'}:{ok:true,msg:'Bridge reachable · database NOT connected — check the bridge config on the practice machine'}):{ok:false,msg:d.error||'Bridge unreachable — save the credentials first, and confirm the tunnel is up.'})}catch(e){setTest({ok:false,msg:e.message})}finally{setTesting(false)}}
 return <Shell title="Configure Dentrix bridge" close={close}><div className="mt-5 space-y-4"><p className="rounded-xl bg-[#e7f0ef] p-3 text-[9px] leading-4">The bridge runs on a practice PC next to the Dentrix database (FairCom c-treeACE over ODBC) and exposes it read-only through an outbound-only tunnel — no router ports. Setup lives in the project bridge/README. The token is stored encrypted server-side.</p><label className="block text-[9px] font-bold">BRIDGE URL<input className="field mono mt-2 text-xs" value={url} onChange={e=>setUrl(e.target.value)} placeholder="https://corinne-bridge.trycloudflare.com"/></label><label className="block text-[9px] font-bold">BRIDGE TOKEN<input className="field mono mt-2 text-xs" type="password" value={token} onChange={e=>setToken(e.target.value)} placeholder="long random string from config.json"/></label>{saved&&<p className="rounded-lg bg-emerald-50 p-3 text-[9px] font-bold text-emerald-700">Bridge credentials saved — encrypted server-side. Run the probe on the practice machine and map the schema before pulling patients.</p>}{error&&<p className="rounded-lg bg-red-50 p-3 text-[9px] text-red-700">{error}</p>}{test&&<p className={`rounded-lg p-3 text-[9px] font-bold ${test.ok?'bg-emerald-50 text-emerald-700':'bg-red-50 text-red-700'}`}>{test.msg}</p>}<div className="flex gap-3"><button disabled={busy} onClick={save} className="flex-1 rounded-xl bg-[#147a76] py-3 text-xs font-bold text-white disabled:opacity-50">{busy?'Saving…':'Save'}</button><button disabled={testing||!saved} onClick={runTest} className="flex-1 rounded-xl border py-3 text-xs font-bold disabled:opacity-50">{testing?'Testing…':'Test connection'}</button></div><p className="text-center text-[8px] text-[#9ab0b4]">Save first — Test checks the saved credentials end to end.</p></div></Shell>
}

 function ConnectorConfig({system,initial,close,save}){ const engines=['PostgreSQL','MySQL / MariaDB','Microsoft SQL Server','Oracle','MongoDB','SQLite','Firestore','REST API','FHIR R4','HL7 v2','Other / custom']
 const[engine,setEngine]=useState(initial?.engine||system[1]),[host,setHost]=useState(initial?.host||''),[port,setPort]=useState(initial?.port||''),[database,setDatabase]=useState(initial?.database||''),[endpoint,setEndpoint]=useState(initial?.endpoint||''),[user,setUser]=useState(initial?.user||''),[password,setPassword]=useState(''),[secret,setSecret]=useState(initial?.secret||`${system[0].toUpperCase().replace(/[^A-Z0-9]+/g,'_')}_SECRET`),[ssl,setSsl]=useState(initial?.ssl??true),[error,setError]=useState(''),[testing,setTesting]=useState(false),[testResult,setTestResult]=useState(null)
 const isApi=['REST API','FHIR R4','HL7 v2'].includes(engine),isFile=engine==='SQLite',isCloud=engine==='Firestore'
 const submit=()=>{if((isApi&&!endpoint)||(!isApi&&!isFile&&!isCloud&&!host)){setError('Complete the required connection fields.');return}save({engine,host,port,database,endpoint,user,secret,ssl,password:password||undefined})}
 const runTest=async()=>{setTesting(true);setTestResult(null);try{const t=await idToken();const r=await fetch('/api/connectors/test',{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${t}`},body:JSON.stringify({system:system[0]})});setTestResult(await r.json())}catch(e){setTestResult({ok:false,error:e.message})}finally{setTesting(false)}}
 return <Shell title={`Configure ${system[0]}`} close={close}><div className="mt-5 space-y-4"><p className="rounded-xl bg-[#e7f0ef] p-3 text-[9px] leading-4">Connections run on the server. Database passwords are encrypted and saved to Firebase — never stored in the browser.</p><label className="block text-[9px] font-bold">PROTOCOL OR DATABASE<select className="field mt-2 text-xs" value={engine} onChange={e=>{setEngine(e.target.value);setTestResult(null)}}>{engines.map(x=><option key={x}>{x}</option>)}</select></label>{isApi?<><label className="block text-[9px] font-bold">BASE ENDPOINT URL<input className="field mono mt-2 text-xs" value={endpoint} onChange={e=>setEndpoint(e.target.value)} placeholder="https://api.vendor.com/fhir/r4"/></label><label className="block text-[9px] font-bold">CREDENTIAL ENV VARIABLE<input className="field mono mt-2 text-xs" value={secret} onChange={e=>setSecret(e.target.value.replace(/[^A-Za-z0-9_]/g,'').toUpperCase())}/></label></>:isFile?<label className="block text-[9px] font-bold">SERVER FILE PATH<input className="field mono mt-2 text-xs" value={database} onChange={e=>setDatabase(e.target.value)}/></label>:isCloud?<label className="block text-[9px] font-bold">FIREBASE PROJECT ID<input className="field mono mt-2 text-xs" value={database} onChange={e=>setDatabase(e.target.value)}/></label>:<><div className="grid grid-cols-[1fr_100px] gap-3"><label className="text-[9px] font-bold">HOST<input className="field mono mt-2 text-xs" value={host} onChange={e=>setHost(e.target.value)} placeholder="localhost"/></label><label className="text-[9px] font-bold">PORT<input className="field mono mt-2 text-xs" value={port} onChange={e=>setPort(e.target.value)} placeholder="3306"/></label></div><label className="block text-[9px] font-bold">DATABASE / INSTANCE<input className="field mono mt-2 text-xs" value={database} onChange={e=>setDatabase(e.target.value)}/></label><div className="grid grid-cols-2 gap-3"><label className="block text-[9px] font-bold">USER<input className="field mono mt-2 text-xs" value={user} onChange={e=>setUser(e.target.value)} placeholder="root"/></label><label className="block text-[9px] font-bold">PASSWORD<input type="password" className="field mono mt-2 text-xs" value={password} onChange={e=>setPassword(e.target.value)} placeholder={initial?'Saved — leave blank to keep':'Password'}/></label></div>{engine==='MySQL / MariaDB'&&<div className="space-y-2"><button onClick={runTest} disabled={testing} className="w-full rounded-xl border border-[#147a76] py-2.5 text-[10px] font-bold text-[#147a76] disabled:opacity-50">{testing?'Testing…':'Test connection'}</button><p className="text-center text-[8px] text-[#71878c]">Tests the saved configuration — save first, then test.</p>{testResult&&(testResult.ok?<p className="rounded-xl bg-emerald-100 p-3 text-[9px] font-bold text-emerald-800">Connected — MySQL {testResult.version} · database "{testResult.database}" · {testResult.tables} tables</p>:<p className="rounded-xl bg-red-50 p-3 text-[9px] font-bold text-red-700">{testResult.error}</p>)}</div>}</>}<label className="flex gap-2 rounded-xl border p-3 text-[10px]"><input type="checkbox" checked={ssl} onChange={e=>setSsl(e.target.checked)}/>Require TLS / SSL</label>{error&&<p className="text-[9px] text-red-700">{error}</p>}<div className="flex gap-3"><button onClick={close} className="flex-1 rounded-xl border py-3 text-xs font-bold">Cancel</button><button onClick={submit} className="flex-1 rounded-xl bg-[#147a76] py-3 text-xs font-bold text-white">Save configuration</button></div></div></Shell>
}function ToolSetup({close}){
 const[data,setData]=useState(null),[error,setError]=useState('')
 useEffect(()=>{(async()=>{try{const t=await idToken();const r=await fetch('/api/insurance/tool-config',{headers:{Authorization:'Bearer '+t},cache:'no-store'});const d=await r.json();if(!r.ok)throw new Error(d.error||'Could not load the tool configuration.');setData(d)}catch(e){setError(e.message)}})()},[])
 return <Shell title="Agent write-back setup" close={close}><div className="mt-5 space-y-3"><p className="rounded-xl bg-[#e7f0ef] p-3 text-[9px] leading-4">Add this webhook tool to the Corinne agent in the ElevenLabs dashboard (Agent → Tools → Webhook tool, paste the JSON). During insurance calls the agent then records confirmed benefits straight into the practice database — appended to the patient chart notes and an insurance-verification row when possible.</p>{error&&<p className="rounded-lg bg-red-50 p-3 text-[9px] text-red-700">{error}</p>}{!data&&!error&&<p className="text-[9px] text-[#71878c]">Loading…</p>}{data&&<><label className="block text-[9px] font-bold">ENDPOINT<input className="field mono mt-2 text-[10px]" readOnly value={data.url}/></label><label className="block text-[9px] font-bold">SECRET HEADER (x-corinne-secret)<input className="field mono mt-2 text-[10px]" readOnly value={data.secret}/></label><label className="block text-[9px] font-bold">TOOL JSON (paste in ElevenLabs → Tools → Import/JSON)<textarea className="field mono mt-2 min-h-44 text-[9px] leading-4" readOnly value={JSON.stringify(data.tool,null,2)}/></label></>}<button onClick={close} className="w-full rounded-xl bg-[#147a76] py-3 text-xs font-bold text-white">Done</button></div></Shell>
}
function Shell({title,close,children}){return <div className="fixed inset-0 z-50 grid place-items-center bg-[#102e35]/50 p-4 backdrop-blur-sm"><div className="w-full max-w-lg rounded-[24px] bg-[#f5f9f9] p-5"><div className="flex justify-between"><h3 className="display text-2xl">{title}</h3><button onClick={close}><X size={18}/></button></div>{children}</div></div>}
function CallModal({close,done}){return <Shell title="Make an outbound call" close={close}><div className="mt-5 space-y-4"><input className="field text-xs" defaultValue="Sarah Mitchell"/><input className="field mono text-xs" defaultValue="(555) 014-4821"/><select className="field text-xs"><option>Confirm appointment</option><option>Verify insurance eligibility</option><option>Post-treatment follow-up</option></select><textarea className="field min-h-24 text-xs" defaultValue="Confirm Monday's 9:30 AM cleaning appointment."/><label className="flex gap-2 text-[10px]"><input type="checkbox" defaultChecked/>Patient consent is on file.</label><Btn onClick={done}><PhoneCall size={14}/>Call patient now</Btn></div></Shell>}
